package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct {
	TcSensor string
	TcF      decimal.Decimal
}

var WsEofFlag string = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)
var WsFreeze int64 = 0
var WsCount int64 = 0
var WsFEd string
var WsCEd string

var tempFile *os.File
var tempReader *bufio.Scanner
var TempRecGlobal TempRec
var inputDone bool

// helpers

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func pow10Dec(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

func truncateHighOrder(val decimal.Decimal, intDigits int, decDigits int) decimal.Decimal {
	// keep low-order intDigits integer digits, preserving sign and fractional part
	// val is assumed already scaled to decDigits (rounded/truncated)
	if intDigits <= 0 {
		return val
	}
	signNeg := val.Sign() < 0
	absVal := val.Abs()
	powTotal := pow10Dec(intDigits + decDigits)
	scaled := absVal.Shift(int32(decDigits)).Truncate(0)
	// scaled is non-negative integer decimal
	modScaled := scaled.Mod(powTotal)
	truncatedAbs := modScaled.Shift(int32(-decDigits))
	if signNeg {
		// if truncatedAbs is zero, keep positive zero (COBOL -0 is 0)
		if truncatedAbs.IsZero() {
			return truncatedAbs
		}
		return truncatedAbs.Neg()
	}
	return truncatedAbs
}

func storeDecimal(val decimal.Decimal, intDigits int, decDigits int, rounded bool) decimal.Decimal {
	var v decimal.Decimal
	if rounded {
		v = val.Round(int32(decDigits))
	} else {
		v = val.Truncate(int32(decDigits))
	}
	// high-order truncation
	v = truncateHighOrder(v, intDigits, decDigits)
	return v
}

func storeInt(val int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// keep low-order digits, positive only for these counters
	// handle negative correctly as well
	if val >= 0 {
		return val % mod
	}
	// for negative, COBOL keeps sign and low-order digits of absolute value
	abs := -val
	abs = abs % mod
	return -abs
}

func formatUneditedInt(val int64, width int) string {
	// zero-padded, high-order truncated already, if negative include minus?
	// For PIC 99 unsigned, just zero padded
	if val < 0 {
		// include sign, pad remaining
		abs := -val
		s := fmt.Sprintf("%0*d", width-1, abs)
		// if still need sign handling? Simplified
		return "-" + s
	}
	return fmt.Sprintf("%0*d", width, val)
}

func formatEditedGeneric(val decimal.Decimal, pic string) string {
	// pic examples: "ZZ9.9" , "-ZZ9.99"
	signPic := false
	signChar := rune(0)
	body := pic
	if len(pic) > 0 && (pic[0] == '-' || pic[0] == '+') {
		signPic = true
		signChar = rune(pic[0])
		body = pic[1:]
	}
	// split body at '.'
	intPic := body
	decPic := ""
	if idx := strings.Index(body, "."); idx >= 0 {
		intPic = body[:idx]
		decPic = body[idx+1:]
	}
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	decDigits := 0
	for _, c := range decPic {
		if c == 'Z' || c == '9' {
			decDigits++
		}
	}

	isNeg := val.Sign() < 0
	absVal := val.Abs()

	// Apply high-order truncation already should have been done by storage,
	// but edited field also drops high-order if larger than picture.
	// We apply modulo on scaled value to ensure width.
	powTotal := pow10Dec(intDigits + decDigits)
	var modScaled decimal.Decimal
	if decDigits > 0 {
		scaled := absVal.Shift(int32(decDigits)).Truncate(0)
		modScaled = scaled.Mod(powTotal)
	} else {
		scaled := absVal.Truncate(0)
		powInt := pow10Dec(intDigits)
		modScaled = scaled.Mod(powInt)
		// keep as scaled (no decimals)
	}

	// Extract integer and fractional strings
	var intPartDec decimal.Decimal
	var fracPartDec decimal.Decimal
	if decDigits > 0 {
		powDec := pow10Dec(decDigits)
		intPartDec = modScaled.Div(powDec).Truncate(0)
		fracPartDec = modScaled.Mod(powDec)
	} else {
		intPartDec = modScaled
		fracPartDec = decimal.Zero
	}

	intVal := intPartDec.IntPart()
	fracVal := fracPartDec.IntPart()

	intStr := fmt.Sprintf("%0*d", intDigits, intVal)
	fracStr := ""
	if decDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", decDigits, fracVal)
	}

	// Apply Z suppression to integer part
	intPicRunes := []rune(intPic)
	// intPicRunes length may include commas; but our intDigits counts only Z/9.
	// For these pictures, intPic == "ZZ9" length==intDigits, no commas.
	// General handling: we need to map digits to digit positions skipping commas?
	// Simplify: assume intPic consists only of Z/9 without commas (true for given pics).
	resultInt := make([]rune, len(intPicRunes))
	suppressed := true
	for i, pc := range intPicRunes {
		// digit char corresponds to position i in intStr (since no commas)
		dc := rune(intStr[i])
		if pc == 'Z' {
			if suppressed && dc == '0' {
				resultInt[i] = ' '
			} else {
				resultInt[i] = dc
				suppressed = false
			}
		} else if pc == '9' {
			resultInt[i] = dc
			suppressed = false
		} else if pc == ',' {
			if suppressed {
				resultInt[i] = ' '
			} else {
				resultInt[i] = ','
			}
		} else {
			resultInt[i] = dc
		}
	}

	var sb strings.Builder
	if signPic {
		if isNeg {
			sb.WriteRune('-')
		} else {
			sb.WriteRune(' ')
		}
	}
	sb.WriteString(string(resultInt))
	if decDigits > 0 {
		sb.WriteRune('.')
		sb.WriteString(fracStr)
	}
	return sb.String()
}

func formatWSFEd(val decimal.Decimal) string {
	return formatEditedGeneric(val, "ZZ9.9")
}
func formatWSCEd(val decimal.Decimal) string {
	return formatEditedGeneric(val, "-ZZ9.99")
}

// COBOL paragraphs as Go functions

func ReadPara() {
	if tempReader == nil {
		WsEofFlag = "Y"
		return
	}
	if tempReader.Scan() {
		line := tempReader.Text()
		// LINE SEQUENTIAL: pad with spaces on right if shorter than record length
		if len(line) < 8 {
			line = line + strings.Repeat(" ", 8-len(line))
		} else if len(line) > 8 {
			line = line[:8]
		}
		// parse
		sensor := line[0:4]
		fStr := line[4:8]
		// fStr digits only
		trimmed := strings.TrimSpace(fStr)
		var iv int64 = 0
		if trimmed != "" {
			// parse digits, ignoring non-digit? assume digits
			for _, ch := range fStr {
				if ch >= '0' && ch <= '9' {
					iv = iv*10 + int64(ch-'0')
				} else if ch == ' ' {
					// treat space as 0? but normally not happen
					iv = iv * 10
				}
			}
		} else {
			iv = 0
		}
		TempRecGlobal.TcSensor = sensor
		TempRecGlobal.TcF = decimal.New(iv, -1)
		WsEofFlag = "N"
	} else {
		WsEofFlag = "Y"
		if err := tempReader.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
		}
	}
}

func ProcessPara() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	// Use decimal arithmetic
	tcF := TempRecGlobal.TcF
	// (TC-F - 32) *5
	diff := tcF.Sub(decimal.NewFromInt(32))
	mul := diff.Mul(decimal.NewFromInt(5))
	div := mul.Div(decimal.NewFromInt(9))
	// Round to scale 2 half away from zero: decimal.Round does half away? shopspring Round uses half up away from zero
	WsC = storeDecimal(div, 3, 2, true)

	if WsC.Sign() < 0 {
		WsFreeze = storeInt(WsFreeze+1, 2)
	}
	WsCount = storeInt(WsCount+1, 2)

	WsFEd = formatWSFEd(tcF)
	WsCEd = formatWSCEd(WsC)

	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	// TC-SENSOR is PIC X(4) exactly 4 chars
	fmt.Printf("%s %sF %sC\n", TempRecGlobal.TcSensor, WsFEd, WsCEd)

	ReadPara()
}

func MainPara() {
	var err error
	tempFile, err = os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty? OPEN INPUT would fail, but we exit
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer tempFile.Close()
	tempReader = bufio.NewScanner(tempFile)
	// allow long lines; set max
	// default 64k is enough for 8 bytes
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE already deferred
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	cntStr := formatUneditedInt(WsCount, 2)
	frzStr := formatUneditedInt(WsFreeze, 2)
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", cntStr, frzStr)
}

func main() {
	MainPara()
}

